  baseSpeed: 89,
  /** 스폰 링 반경을 유도하는 **직선 환산** 접근 시간(초). 링 반경 = outerR + baseSpeed × 이 값.
   * BALANCE §1의 등재값(중앙값 ~7.3초, 방향별 4~9초)은 **실측**이고, 실측이 직선보다 12% 긴 것은
   * 적이 직선이 아니라 플로우필드를 따라(지형 우회 + 감속) 오기 때문이다 — 감독 #8 ①로 §1이
   * 7.3으로 갱신됐다. 여기 6.5를 줄이면 링이 맵 가로 반폭(792) 아래로 내려가 사각 링이 된다 */
  approachSec: 6.5,
  /** BALANCE §1 등재값 = **실측** 접근 중앙값(초). probe가 이 값과 대조한다 (감독 #8 ①) */
  approachMedianSec: 7.3,
  /** 스폰 링이 **맵 사각형 밖**임을 보장하는 여유(월드). §5.0 "맵 가장자리 바깥에서 진입".
   * 감독 #7 ②로 링이 원형이 되면서 의미가 바뀌었다 — 링 반경은 이제 접근 시간에서 직접 유도되고
   * (`outerR + baseSpeed × approachSec`), 이 값은 **대각선 방향에서만 걸리는 클램프**의 여유다.
   * 90(사각 링 시절의 하한 보정값)일 필요가 없어져 "적 스프라이트가 화면 밖"인 최소치로 줄였다 */
  spawnMargin: 24,
  /** 한 무리(burst)가 흩어지는 반경(월드). 원형 링에서는 **접선 + 바깥쪽으로만** 흩어진다 —
   * 안쪽으로 흩어지면 원형화로 균일하게 만든 접근 거리가 다시 벌어진다 */
