  tesla: [
    { id: "arcstorm", name: "광역 방전", sub: "체인 6 · 단발 절반 · 사거리 −20%", dmg: 0.5, range: 0.8, set: { chain: 6, chainJump: 0.35 }, fx: "wide" },
    { id: "focus", name: "집중 방전", sub: "단발 ×3 · 체인 없음 · 사거리 ×1.2(0.96)", dmg: 3, range: 1.2, set: { chain: 1 }, fx: "pierce" },
  ],
  // 저격포 — §4가 "관통·광역 없음"을 대가로 적은 무기라, 분기 하나가 그 대가를 되사는 자리다
  sniper: [
    { id: "apshell", name: "철갑 저격", sub: "단발 ×2 · 성벽 1장 관통", dmg: 2, set: { pierceWalls: 1 }, fx: "pierce" },
    { id: "rapid", name: "속사 저격", sub: "연사 ×2 · 사거리 −15%", dmg: 0.5, range: 0.85, fx: "wide" },
  ],
  // 레이저 — 지속 조사(ramp)를 «키울 것인가 버릴 것인가». ramp 1 = 증폭 없음
  laser: [
    { id: "beam", name: "지속 조사", sub: "증폭 ×2.5(4초) · 사거리 −15%", dmg: 1, range: 0.85, set: { ramp: 2.5, rampSec: 4 }, fx: "pierce" },
    { id: "scatter", name: "확산 레이저", sub: "증폭 없음 · 착탄 광역 0.15 · 사거리 +30%", dmg: 1, range: 1.3, set: { ramp: 1, hitSplash: 0.15 }, fx: "wide" },
  ],
