  cannon: [
    { id: "he", name: "고폭탄", sub: "착탄 광역 0.35 · 사거리 −15%", dmg: 1, range: 0.85, set: { hitSplash: 0.35 }, fx: "wide" },
    { id: "apcannon", name: "철갑 관통탄", sub: "단발 ×2 · 광역 없음 · 성벽 관통 · 사거리 +25%", dmg: 2, range: 1.25, set: { hitSplash: 0, pierceWalls: 1 }, fx: "pierce" },
  ],
  // 미사일 포드 — 곡사 최장을 «더 멀리 vs 더 굵게»
  missile: [
    { id: "long", name: "장사정탄", sub: "사거리 +30% · 착탄 반경 0.12", dmg: 1, range: 1.3, set: { splash: 0.12 }, fx: "pierce" },
    { id: "heavy", name: "중(重)탄두", sub: "단발 ×2 · 착탄 반경 0.3 · 사거리 −20%", dmg: 2, range: 0.8, set: { splash: 0.3 }, fx: "wide" },
  ],
  // 다연장 — 분산 살보의 «넓이 vs 밀도». 발당 피해는 salvo로 나뉘므로 명목은 그대로다
  mlrs: [
    { id: "saturate", name: "포화 사격", sub: "12발 · 산포 0.5 · 사거리 −10%", dmg: 1, range: 0.9, set: { salvo: 12, spread: 0.5 }, fx: "wide" },
    { id: "precision", name: "정밀 로켓", sub: "2발 · 산포 0.12 · 착탄 반경 0.25 · 사거리 +15%", dmg: 1, range: 1.15, set: { salvo: 2, spread: 0.12, splash: 0.25 }, fx: "pierce" },
  ],
