/** **런의 경로 — 어느 스테이지에서 어느 맵을 도는가** (DESIGN §0.7 O ⓑ · 5차 A3 · 감독 #72 ③).
 * 「열차가 다음 구역으로 이동한다」가 이 게임의 서사이고, 36웨이브를 한 배경으로 도는 반복감을
 * 가장 크게 더는 것이 이것이다. **전환의 자리는 정차뿐이다**(스테이지 경계 = 필드가 비는 유일한
 * 프레임 · save.ts 머리말과 같은 근거).
 *
 * · 스테이지 1~6 (웨이브 1~18) = **구릉 평원** · 스테이지 7~12 (웨이브 19~36) = **폐허 도시**
 *
 * ⚠ **`?map=`이 주어지면 그 맵으로 런 전체가 고정된다**(= 경로를 끈다). 단일 맵 회귀 컷
 * (`?map=plains` 9시드 · `?map=city` 9시드)이 그 문으로 남고, **파라미터 없는 기본 런이 경로 런**이다 */
export const ROUTE: { readonly fromStage: number; readonly map: MapId }[] = [
  { fromStage: 1, map: "plains" },
  { fromStage: 7, map: "city" },
];

/** 스테이지 `stage`가 도는 맵. 경로가 비어 있을 수 없으므로 첫 구간이 언제나 답을 낸다 */
export const routeMapOf = (stage: number): MapId => {
  let id = ROUTE[0].map;
  for (const leg of ROUTE) if (stage >= leg.fromStage) id = leg.map;
  return id;
};

/** `stage`가 속한 구간의 **첫 스테이지** (= 열차가 그 구역에 들어선 자리). 새 구역의 지형은 그
 * 자리에서 «초기 채움»으로 서고(map.ts `stageTerrain`의 `fresh`), 앞 구간의 보충은 **다른 판에
 * 얹힌 것이라 이 판에 실려 오지 않는다** */
export const routeLegStartOf = (stage: number): number => {
  let from = ROUTE[0].fromStage;
  for (const leg of ROUTE) if (stage >= leg.fromStage) from = leg.fromStage;
  return from;
};

/** **이 런이 실제로 쓰는 드랍 가치**(§0.5 `MULT.drop` · 맵 칸 `MAPS[id].drop` · QA `?drop=`).
 * 읽는 자리가 넷이라(`combat.ts dropScrap()` · main.ts의 §2 수입표 · probe `drops.expected` ·
 * probe `multNow`) **한 문을 지나야 한다** — `MULT.drop`을 직접 읽는 코드는 맵 칸도 QA도 안 걸린다 */
export const dropValueOf = (id: MapId): number => qaDrop ?? MAPS[id].drop;
// ⚠ **`MULT.drop`은 «런타임에 안 읽힌다»** (iter153이 밟았다). 위 한 줄이 유일한 문이고 그것이 읽는
// 것은 **맵 칸**이다 — 그래서 감독 지시(INBOX #74 ① 「`MULT.drop` 0.2 → 2.0」)를 그 상수에만 적으면
// **화면에도 시뮬에도 한 자도 안 반영된다**(실측: 시작 편성만 6칸이 된 컷이 경로 9시드 **0/9**).
// 그래서 **맵 칸 둘을 지시값으로 내렸다**: 평원 0.21 → **2.0** · 도시 0.30 → **2.0**.
// ⚠ **그 대가로 도시 칸의 «×1.43»이 잠정 정지된다** — 도시가 평원보다 드랍이 셌던 것은 iter140이
// 도시 완주를 6/9 → 9/9로 되돌린 손잡이였다(§0.7-C 아래 표 16). **감독 판정 대기**(STATUS 미결).
// ⚠ **비를 지키려고 ×10을 각각 걸어 보았고(2.1 / 3.0) 그 컷은 8/9다** — s9가 웨이브 18에서 죽는다.
// 지시가 근거로 든 실측은 **`?drop=2.0`(= 두 맵 한 값)**이라 그 컷을 그대로 세우는 쪽을 골랐다.
// ⚠ **옛 컷은 «한 손잡이»로 못 되살린다** — `?drop=`은 두 맵을 한 값으로 덮는다. 평원 단독은
// `?drop=0.21&map=plains` · 도시 단독은 `?drop=0.3&map=city`이고, **경로(평원 18 + 도시 18)의 옛
// 컷은 손잡이 하나로 재현이 안 된다**(STATUS 함정).

/** **2단 파괴의 두 눈금** (DESIGN §0.7 J1 · BALANCE §0.7). 맵과 무관한 «단계의 정의»라
 * MAPS가 아니라 여기 든다 — 어느 맵이 2단 파괴를 켜든 단계는 한 벌이어야 한다.
 *  · `at` = **1차 파괴 = HP 50%**(감독 못박음). 이 아래로 내려가면 외형이 무너지고 차단이 약해진다
 *  · `losR` = 1차 파괴 뒤의 **사선 차단 반경 배수**. **BALANCE §0.7-B 등재값**(감독 #64 ④).
 *    도시 맵에서 「차단」은 곧 **「내 탄이 거기 맞는다」**이므로(J1), 상자가 작아지는 것이
 *    정본 문면의 「판정 반경 축소 + 관통 허용」 둘을 한 값으로 낸다: 가장자리를 스치던 선은
 *    이제 **지나가고**(관통), 한복판을 지나는 선만 여전히 막힌다(축소된 반경) */
export const CRACK = {
  at: 0.5,
  losR: 0.55,
} as const;

/** **폭발 지물 = 폐주유소의 연료 탱크** (DESIGN §0.7 J1-c · 감독 #66 ⑤ 「완파될 때 연료 탱크가
 * 터지듯 큰 폭발과 함께 잔해가 된다」). 규약 셋이 이 네 칸에서 나온다:
 *  ⓐ **2차 파괴 순간 광역 폭발** — `blastR`·`dmg`
 *  ⓑ **주변 지물에도 피해**(연쇄 철거) — `terrainMult`
 *  ⓒ **「언제 터뜨릴지」를 플레이어가 고른다** — `hp`가 그 값이다. 지금 이 지물을 때릴 수 있는
 *     경로는 **조준 포격 하나**뿐이라(구운 지물은 기본적으로 사선을 안 막아 직사 표적이 안 된다 ·
 *     `map.ts solidCover`) HP를 포격 발수로 읽는 것이 정확하다
 *
 * ⚠ **BALANCE 미등재 — 루프 실측 제안 · 감독 등재 대기다**(감독 #66 ⑤ 「반경·피해·연쇄 여부는
 *    루프 실측 제안 → 감독 등재」). 사다리 손잡이는 QA `?fuelhp=`이고 근거는 STATUS 「미결 질문」에 있다.
 *  · `hp 240` = **조준 포격 2발**(ARTILLERY.dmg 40 × terrainMult 3 = 120/발 = 성벽 1장).
 *    1발이면 성벽 한 장과 값이 같아져 「고르는 것」이 아니라 «지나가다 터지는 것»이 된다 —
 *    2발 = 쿨다운 2회분이 ⓒ의 「고른다」에 값을 매긴다. 사다리 = 120 / **240** / 360
 *  · `blastR 2.4` = 지물 **판정 반경 배수**(월드 49.8 → **119.5**). 월드 상수로 두지 않는 이유는
 *    그림이 갈리면 판정원도 갈리기 때문이다(`TERRAIN_CITY`의 반경이 실측값이다). 조준 포격의
 *    착탄 반경(78.6)의 **1.52배** — 「내가 부른 폭발보다 큰 폭발」이어야 ⓐ의 「큰」이 화면에서 읽힌다
 *  · `dmg 90` = 조준 포격 한 발(40)의 2.25배. 웨이브 4~19 잡몹을 «한 방»에 눕히지 않는 선에서
 *    가장 큰 값이다(불변식 6의 예외는 무기 3종뿐이고 이것은 무기가 아니다)
 *  · `terrainMult 3` = ARTILLERY와 **같은 배수**(지형 피해는 「철거 전용급」이라는 §4 비고와 한 벌).
 *    90 × 3 = 270 ≥ 도시 성벽 HP 120 → **연쇄 철거가 1발로 성립한다**(ⓑ의 판정선) */
export const FUEL = {
  hp: 240,
  blastR: 2.4,
  dmg: 90,
  terrainMult: 3,
} as const;


/** 조준 포격 = 기관차 주포 (BALANCE §4 마지막 행 / DESIGN §6.2). 플레이어 개입 1종 —
 * 자동 사격을 하지 않고, 클릭한 지점에 delaySec 뒤 착탄한다. 사거리 무제한.
 * `radius`의 단위는 WEAPONS.range와 같은 "루프 반경 = 1"이라 월드 환산은 map.outerR를 곱한다 */
export const ARTILLERY = {
  dmg: 40,
  radius: 0.35,
  /** 지형 피해 배수 (§4 비고 "철거 전용급"). 40 × 3 = 120 = 성벽 HP 1발 (TERRAIN.wallHp) */
  terrainMult: 3,
  /** 클릭 → 착탄 지연(초). DESIGN §6.2 "1.5초 후 착탄" */
  delaySec: 1.5,
  /** 쿨다운(초). BALANCE §4 "쿨 10s" (DESIGN §6.2의 8~12s 범위 중앙) */
  cooldownSec: 10,
} as const;

/** 스크랩 드랍·수집 (DESIGN §7.1 "필드에 떨어지며, 열차 수집칸의 반경 안을 지날 때 흡수").
 * 드랍 **값**은 BALANCE §2가 정본(ENEMY_STATS.scrap / TERRAIN.wallScrap)이고, 여기 있는 것은
 * 수집칸의 흡수 파라미터다 — 감독 #4 ①로 **BALANCE §2에 정식 등재**됐다(정본). */
export const COLLECT = {
  /** 흡수 반경. 단위는 WEAPONS.range와 같은 "루프 반경 = 1"(× map.outerR = 월드) → 223.
   * 레일 ±223의 띠 = 코어 주변(레일→코어 최단 178)부터 기관총 사거리(267) 대부분까지 훑는다.
   * BALANCE §2의 기대 수입(스테이지1 ~150)이 성립하려면 회수율이 높아야 해서 잡은 값 —
   * 0.75(=167)면 실측 회수율 0.69로 §2에 30% 미달했다. 레일건 사거리(2.0) 끝의 처치는 여전히 못 줍는다 */
  radius: 1.0,
  /** 반경 안에 든 드랍이 수집칸으로 끌려오는 속도(월드/초). 열차 속도(≈78)보다 빨라야 따라잡는다 */
  pullSpeed: 220,
  /** 이 거리 안이면 획득 */
  pickup: 14,
  /** **드랍 당김** — 처치 지점에서 레일 쪽으로 끌어당겨 떨구는 최대 거리. 단위는 radius와 같은
   * "루프 반경 = 1"(× map.outerR) → 123.5 월드. **BALANCE §2 등재값**(감독 #29 ① — 선택지 ⓓ).
   * 이유: 수집 반경(1.0 = 224.6)보다 §4 장사거리(레일건 2.0 = 449 · 박격포 1.8 = 404)가 커서
   * **강한 편성일수록 자기 수입을 스스로 지우는** 산술 모순이 있었다(iter42 실측 회수율 0.22~0.30).
   * 당김을 유한하게 둬 §7.1의 "회수 실패"는 살려 둔다 — 0.55에서 기준 9칸 Lv6이 **0.75~0.76**,
   * 시작 4칸이 0.95~0.97이다(감독 지정 목표 0.7~0.8). 레일 **너머로는 안 넘긴다**(combat.pullToRail) */
  pull: 0.55,
  /** 필드에 떨어지는 스크랩의 총량 배수 (감독 #4 ②). BALANCE §2의 기대 수입(150/250/400)이
   * **실효(회수 후) 기준**으로 재정의됐고 실측 회수율이 ~0.85라, 드랍 총량을 그만큼 올려야
   * 실효가 표값에 맞는다(1/0.85 ≈ 1.15). §2의 드랍원별 값(좀비 2 …)은 정본이므로 손대지 않고
   * 여기서 총량만 곱한다 — 표값 쪽으로 옮기고 싶으면 이 상수를 1로 두고 §2를 고치면 된다 */
  dropMult: 1.15,
  /** 필드 드랍 수명(초). **BALANCE §2 등재값** (감독 #12 ③ 승인 — "회수 실패가 존재해야 한다"와
   * "영구 축적"은 다르다). 수집 반경(223) 밖에 떨어진 드랍은 영영 안 줍히는데 수명이 없어 런 내내
   * 쌓였고, iter18~19 판정 컷에서 **화면의 주된 시각 노이즈가 적이 아니라 금색 스파클**이었다
   * (드랍 65~81개 vs 적 10~14기). 수명이 짧으면 §2 회수율이 떨어져 기대 수입이 무너지므로,
   * 25초 = 열차 1바퀴(14초)를 확실히 넘기는 값이다 — 반경 안의 드랍은 여전히 다 회수된다 */
  lifeSec: 25,
  /** 드랍 표시 크기(월드). scrap 타일은 그림 주위 여백이 넓어 26이면 화면에서 8px짜리 점으로 보였다 —
   * 적(22)보다 크게 잡아야 "주울 것이 떨어졌다"가 읽힌다 */
  size: 44,
} as const;
